package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class TarUtils_formatNameBytes_TriageGen2Test {

    /**
     * Mock helper to create a ByteBuffer wrap
     */
    private ByteBuffer createBuffer(String content) {
        return ByteBuffer.wrap(content.getBytes());
    }

    @Test
    public void testFormatNameBytes_StandardCase() throws IOException {
        String name = "test.txt";
        int length = 10;
        int offset = 0;
        byte[] buf = new byte[length];
        ZipEncoding encoding = mock(ZipEncoding.class);

        // Mock encoding to return "test.txt" bytes
        when(encoding.encode("test.txt")).thenReturn(createBuffer("test.txt"));

        int result = TarUtils.formatNameBytes(name, buf, offset, length, encoding);

        // Expected: "test.txt" + 2 NUL bytes (total 10)
        assertEquals(offset + length, result);
        assertEquals("test.txt\0\0", new String(buf));
    }

    @Test
    public void testFormatNameBytes_TruncationRequired() throws IOException {
        String name = "verylongname.txt";
        int length = 5; // Small buffer
        int offset = 0;
        byte[] buf = new byte[length];
        ZipEncoding encoding = mock(ZipEncoding.class);

        // Simulate the loop: 
        // 1. encode("verylongname.txt") -> too long
        // 2. encode("verylongname.tx") -> too long
        // ...
        // 3. encode("veryl") -> fits
        when(encoding.encode("verylongname.txt")).thenReturn(createBuffer("verylongname.txt"));
        when(encoding.encode("verylongname.tx")).thenReturn(createBuffer("verylongname.tx"));
        when(encoding.encode("verylongname.t")).thenReturn(createBuffer("verylongname.t"));
        when(encoding.encode("verylongname")).thenReturn(createBuffer("verylongname"));
        when(encoding.encode("verylongnam")).thenReturn(createBuffer("verylongnam"));
        when(encoding.encode("verylongna")).thenReturn(createBuffer("verylongna"));
        when(encoding.encode("verylongn")).thenReturn(createBuffer("verylongn"));
        when(encoding.encode("verylong")).thenReturn(createBuffer("verylong"));
        when(encoding.encode("verylon")).thenReturn(createBuffer("verylon"));
        when(encoding.encode("verylo")).thenReturn(createBuffer("verylo"));
        when(encoding.encode("veryl")).thenReturn(createBuffer("veryl"));

        int result = TarUtils.formatNameBytes(name, buf, offset, length, encoding);

        assertEquals(offset + length, result);
        assertEquals("veryl", new String(buf));
    }

    @Test
    public void testFormatNameBytes_EmptyString() throws IOException {
        String name = "";
        int length = 5;
        int offset = 0;
        byte[] buf = new byte[length];
        ZipEncoding encoding = mock(ZipEncoding.class);

        when(encoding.encode("")).thenReturn(createBuffer(""));

        int result = TarUtils.formatNameBytes(name, buf, offset, length, encoding);

        assertEquals(offset + length, result);
        // Should be all NULs
        for (byte b : buf) {
            assertEquals(0, b);
        }
    }

    @Test
    public void testFormatNameBytes_OffsetUsage() throws IOException {
        String name = "abc";
        int length = 5;
        int offset = 2;
        byte[] buf = new byte[7]; // [0, 0, 'a', 'b', 'c', 0, 0]
        ZipEncoding encoding = mock(ZipEncoding.class);

        when(encoding.encode("abc")).thenReturn(createBuffer("abc"));

        int result = TarUtils.formatNameBytes(name, buf, offset, length, encoding);

        assertEquals(offset + length, result);
        assertEquals(0, buf[0]);
        assertEquals(0, buf[1]);
        assertEquals('a', buf[2]);
        assertEquals('b', buf[3]);
        assertEquals('c', buf[4]);
        assertEquals(0, buf[5]);
        assertEquals(0, buf[6]);
    }

    @Test
    public void testFormatNameBytes_ExtremeTruncation() throws IOException {
        String name = "a";
        int length = 5;
        int offset = 0;
        byte[] buf = new byte[length];
        ZipEncoding encoding = mock(ZipEncoding.class);

        // If even the first char is too long (unlikely with standard encodings but tests the while loop condition 'len > 0')
        // We simulate encoding "a" results in 10 bytes, but length is 5.
        // The loop will try substring(0, 0) which is ""
        when(encoding.encode("a")).thenReturn(createBuffer("aaaaaaaaaa"));
        when(encoding.encode("")).thenReturn(createBuffer(""));

        int result = TarUtils.formatNameBytes(name, buf, offset, length, encoding);

        assertEquals(offset + length, result);
        for (byte b : buf) {
            assertEquals(0, b);
        }
    }

    @Test(expected = IOException.class)
    public void testFormatNameBytes_ThrowsIOException() throws IOException {
        String name = "test";
        int length = 10;
        int offset = 0;
        byte[] buf = new byte[length];
        ZipEncoding encoding = mock(ZipEncoding.class);

        when(encoding.encode(anyString())).thenThrow(new IOException("Simulated IO Error"));

        TarUtils.formatNameBytes(name, buf, offset, length, encoding);
    }
}
